<?php $pages=max(1,(int)ceil($total/20)); ?>
<div class="page-header"><div><span class="staff-eyebrow">Udyam Ventures</span><h2>Staff Management</h2><p>Internal employee directory, reporting structure and business cards.</p></div><div class="staff-header-actions"><a class="btn" href="<?=htmlspecialchars(url('/admin/staff/export?'.http_build_query(['search'=>$search,'status'=>$status,'department'=>$department])))?>"><i data-lucide="download"></i> Export CSV</a><a class="btn btn-primary" href="<?=htmlspecialchars(url('/admin/staff/create'))?>"><i data-lucide="user-plus"></i> Add Staff</a></div></div>
<div class="staff-summary-row"><div><strong><?=number_format($total)?></strong><span>Matching staff</span></div><div><strong><?=count(array_filter($staff,fn($s)=>$s['status']==='active'))?></strong><span>Active on this page</span></div><div><strong><?=count(array_filter($staff,fn($s)=>$s['profile_photo_media_id']))?></strong><span>Profiles with photos</span></div><div><strong><?=count(array_filter($staff,fn($s)=>$s['card_status']==='enabled'))?></strong><span>Live cards</span></div></div>
<div class="card"><form method="get" class="filters-bar staff-filters"><input class="form-control" name="search" value="<?=htmlspecialchars($search)?>" placeholder="Search name, code, email or mobile…"><select class="form-control" name="status"><option value="">All statuses</option><?php foreach(['active'=>'Active','inactive'=>'Inactive','on_leave'=>'On Leave','resigned'=>'Resigned','suspended'=>'Suspended'] as $value=>$label):?><option value="<?=$value?>" <?=$status===$value?'selected':''?>><?=$label?></option><?php endforeach?></select><select class="form-control" name="department"><option value="">All departments</option><?php foreach($departments as $item):?><option value="<?=htmlspecialchars($item)?>" <?=$department===$item?'selected':''?>><?=htmlspecialchars($item)?></option><?php endforeach?></select><button class="btn" type="submit">Filter</button><?php if($search||$status||$department):?><a class="btn btn-ghost" href="<?=htmlspecialchars(url('/admin/staff'))?>">Clear</a><?php endif?></form>
<div class="table-responsive"><table class="table staff-table"><thead><tr><th>Staff</th><th>Role</th><th>Contact</th><th>Manager</th><th>Status</th><th>Business Card</th><th>Actions</th></tr></thead><tbody>
<?php if($staff===[]):?><tr><td colspan="7"><div class="staff-empty"><i data-lucide="users"></i><strong>No staff members found</strong><span>Adjust the filters or add the first staff member.</span></div></td></tr>
<?php else:foreach($staff as $item):?><tr><td><a class="staff-person" href="<?=htmlspecialchars(url('/admin/staff/'.$item['id']))?>"><?php if($item['photo_filename']):?><img src="<?=htmlspecialchars(media_url(['folder'=>$item['photo_folder'],'filename'=>$item['photo_filename']]))?>" alt=""><?php else:?><span><?=htmlspecialchars(strtoupper(substr($item['first_name'],0,1).substr($item['last_name'],0,1)))?></span><?php endif?><div><strong><?=htmlspecialchars($item['display_name'])?></strong><small><?=htmlspecialchars($item['employee_code'])?></small></div></a></td><td><strong><?=htmlspecialchars($item['designation'])?></strong><small class="table-subtext"><?=htmlspecialchars($item['department'])?></small></td><td><a href="mailto:<?=htmlspecialchars($item['email'])?>"><?=htmlspecialchars($item['email'])?></a><small class="table-subtext"><?=htmlspecialchars($item['mobile'])?></small></td><td><?=htmlspecialchars($item['manager_name']?:'—')?></td><td><span class="staff-status status-<?=htmlspecialchars($item['status'])?>"><?=htmlspecialchars(ucwords(str_replace('_',' ',$item['status'])))?></span></td><td><?php if($item['public_slug']):?><div class="staff-card-actions"><a href="<?=htmlspecialchars(url('/card/'.$item['public_slug']))?>" target="_blank">View Card</a><a href="<?=htmlspecialchars(url('/admin/digital-business-cards/'.$item['id'].'/qr?format=svg'))?>" target="_blank">QR Code</a><a href="<?=htmlspecialchars(url('/admin/digital-business-cards/'.$item['id'].'/qr?download=1'))?>">Download QR</a></div><?php else:?>—<?php endif?></td><td><div class="row-actions"><a class="btn btn-sm" href="<?=htmlspecialchars(url('/admin/staff/'.$item['id']))?>">View</a><a class="btn btn-sm" href="<?=htmlspecialchars(url('/admin/staff/'.$item['id'].'/edit'))?>">Edit</a></div></td></tr><?php endforeach;endif?></tbody></table></div>
<?php if($pages>1):?><div class="staff-pagination"><?php for($i=1;$i<=$pages;$i++):?><a class="<?=$i===$page?'active':''?>" href="<?=htmlspecialchars(url('/admin/staff?'.http_build_query(['page'=>$i,'search'=>$search,'status'=>$status,'department'=>$department])))?>"><?=$i?></a><?php endfor?></div><?php endif?></div>
